#!/bin/bash
set -euo pipefail

# Test: Handoff generation time must be under 60 seconds end-to-end
# Generated by /qa on 2026-05-13 for dev/oguzhan/handoff-perf-test
# Covers: Python renderer, API publish endpoint, full round-trip

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
FIXTURE="$SCRIPT_DIR/bin/tests/test-handoff-render-onthefly.json"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; }

echo "Testing: Handoff generation time"
echo ""

if [ ! -f "$FIXTURE" ]; then
  fail "Fixture file missing: $FIXTURE"
  echo ""
  echo "$PASS passed, $FAIL failed"
  exit 1
fi

# ── Test 1: Python renderer speed ─────────────────────────────────
echo "## Test 1 — Python renderer speed (10 runs, worst-case)"

RENDER_RESULT=$(python3 -c "
import json, sys, time
sys.path.insert(0, '$SCRIPT_DIR')
from api.handoff_render import render_handoff_html

with open('$FIXTURE') as f:
    cj = json.load(f)

render_handoff_html(cj)

times = []
for _ in range(10):
    start = time.perf_counter()
    html = render_handoff_html(cj)
    elapsed = (time.perf_counter() - start) * 1000
    times.append(elapsed)

avg = sum(times) / len(times)
worst = max(times)
size = len(html)
print(f'{avg:.1f} {worst:.1f} {size}')
" 2>&1)

AVG_MS=$(echo "$RENDER_RESULT" | awk '{print $1}')
WORST_MS=$(echo "$RENDER_RESULT" | awk '{print $2}')
HTML_SIZE=$(echo "$RENDER_RESULT" | awk '{print $3}')

echo "  avg: ${AVG_MS}ms, worst: ${WORST_MS}ms, output: ${HTML_SIZE} bytes"

WORST_INT=$(printf '%.0f' "$WORST_MS")
if [ "$WORST_INT" -lt 500 ]; then
  pass "Render ${WORST_MS}ms < 500ms"
else
  fail "Render ${WORST_MS}ms exceeds 500ms"
fi

# ── Test 2: Output completeness ───────────────────────────────────
echo ""
echo "## Test 2 — Output completeness (25 checks)"

COMP_RESULT=$(python3 -c "
import json, sys
sys.path.insert(0, '$SCRIPT_DIR')
from api.handoff_render import render_handoff_html

with open('$FIXTURE') as f:
    cj = json.load(f)
html = render_handoff_html(cj).decode('utf-8')

checks = [
    'og:title', 'application/ld+json', 'eg-theme-toggle',
    'data-theme', 'font-serif', 'eg-badge-active',
    'eg-hero', 'Open in Claude', 'Open in ChatGPT',
    'EGREGORE HANDOFF', 'eg-md-table', 'Key Decisions',
    'Open Threads', 'Next Steps', 'Repo State', 'References',
    'Chain (', 'Respond to this handoff', 'copy-ctx', 'browser confirmation link',
    'eg-footer', '@media (max-width: 640px)', '@media print',
]

p = 0
f = 0
fails = []
for c in checks:
    if c in html:
        p += 1
    else:
        f += 1
        fails.append(c)

# Check no visible agent blocks
cs = html.find('<!--')
ce = html.find('-->', cs) if cs >= 0 else -1
outside = html[:cs] + html[ce+3:] if cs >= 0 else html
for sym, name in [('↳', 'arrow'), ('⌬', 'delta')]:
    if sym not in outside:
        p += 1
    else:
        f += 1
        fails.append(f'visible-{name}')

print(f'{p} {f}')
if fails:
    print(' '.join(fails))
" 2>&1)

COMP_P=$(echo "$COMP_RESULT" | head -1 | awk '{print $1}')
COMP_F=$(echo "$COMP_RESULT" | head -1 | awk '{print $2}')

if [ "$COMP_F" = "0" ]; then
  pass "All $COMP_P output checks passed"
else
  COMP_FAILS=$(echo "$COMP_RESULT" | tail -1)
  fail "$COMP_F checks failed: $COMP_FAILS"
fi

# ── Test 3: Publish round-trip (live API) ─────────────────────────
echo ""
echo "## Test 3 — Publish round-trip (live API)"

# Build publish payload to temp file
PAYLOAD_FILE=$(mktemp)
python3 -c "
import json
with open('$FIXTURE') as f:
    cj = json.load(f)
if 'id' in cj:
    del cj['id']
with open('$PAYLOAD_FILE', 'w') as out:
    json.dump({'identity':{'email':'perf-test@egregore.xyz','name':'Perf Test'},'artifact':cj}, out)
" 2>/dev/null

CLIENT_ID="perf-test-$(date +%s)"

# Hit Railway directly to avoid redirect body-drop
API_URL=$(jq -r '.api_url // "https://egregore-production-55f2.up.railway.app"' "$SCRIPT_DIR/egregore.json" 2>/dev/null)
CURL_OUT=$(curl -s -X POST \
  -H "Content-Type: application/json" \
  -H "X-Egregore-Client: $CLIENT_ID" \
  -d @"$PAYLOAD_FILE" \
  -w "\n%{http_code} %{time_total}" \
  "${API_URL}/api/artifacts/handoff" 2>&1)

rm -f "$PAYLOAD_FILE"

CURL_META=$(echo "$CURL_OUT" | tail -1)
CURL_BODY=$(echo "$CURL_OUT" | sed '$d')
HTTP_CODE=$(echo "$CURL_META" | awk '{print $1}')
CURL_TIME=$(echo "$CURL_META" | awk '{print $2}')
PUB_MS=$(python3 -c "print(int(float('$CURL_TIME') * 1000))" 2>/dev/null)
PUB_URL=$(echo "$CURL_BODY" | python3 -c "import json,sys; print(json.load(sys.stdin).get('url',''))" 2>/dev/null || echo "")

if [ "$HTTP_CODE" = "200" ] && [ -n "$PUB_URL" ]; then
  PUBLISH_RESULT="OK $PUB_MS $PUB_URL"
else
  PUBLISH_RESULT="ERR $PUB_MS $HTTP_CODE"
fi

PUB_STATUS=$(echo "$PUBLISH_RESULT" | awk '{print $1}')
PUB_MS=$(echo "$PUBLISH_RESULT" | awk '{print $2}')
PUB_URL=$(echo "$PUBLISH_RESULT" | awk '{print $3}')

if [ "$PUB_STATUS" = "OK" ]; then
  echo "  publish: ${PUB_MS}ms → $PUB_URL"
  if [ "$PUB_MS" -lt 10000 ]; then
    pass "Publish ${PUB_MS}ms < 10s"
  else
    fail "Publish ${PUB_MS}ms exceeds 10s"
  fi
else
  echo "  publish failed: $PUBLISH_RESULT"
  fail "Publish error" "$PUBLISH_RESULT"
fi

# ── Test 4: Fetch rendered page ───────────────────────────────────
echo ""
echo "## Test 4 — Fetch rendered page (on-the-fly render)"

FETCH_MS=0
if [ "$PUB_STATUS" = "OK" ] && [ -n "$PUB_URL" ]; then
  FETCH_OUT=$(curl -s -L -o /dev/null -w "%{http_code} %{time_total} %{size_download}" \
    -H "Accept: text/html" "$PUB_URL" 2>&1)
  F_CODE=$(echo "$FETCH_OUT" | awk '{print $1}')
  F_TIME=$(echo "$FETCH_OUT" | awk '{print $2}')
  F_SIZE=$(echo "$FETCH_OUT" | awk '{print $3}')
  FETCH_MS=$(python3 -c "print(int(float('$F_TIME') * 1000))" 2>/dev/null)

  if [ "$F_CODE" = "200" ]; then
    echo "  fetch: ${FETCH_MS}ms, ${F_SIZE} bytes"
    if [ "$FETCH_MS" -lt 10000 ]; then
      pass "Fetch ${FETCH_MS}ms < 10s"
    else
      fail "Fetch ${FETCH_MS}ms exceeds 10s"
    fi
  else
    echo "  fetch failed: HTTP $F_CODE"
    fail "Fetch HTTP $F_CODE"
  fi
else
  echo "  skipped (publish failed)"
fi

# ── Test 5: Total budget ─────────────────────────────────────────
echo ""
echo "## Test 5 — Total budget (render + publish + fetch < 60s)"

if [ "$PUB_STATUS" = "OK" ]; then
  TOTAL=$((WORST_INT + PUB_MS + FETCH_MS))
  echo "  render(${WORST_INT}ms) + publish(${PUB_MS}ms) + fetch(${FETCH_MS}ms) = ${TOTAL}ms"
  if [ "$TOTAL" -lt 60000 ]; then
    pass "Total ${TOTAL}ms < 60s budget"
  else
    fail "Total ${TOTAL}ms exceeds 60s budget"
  fi
fi

# ── Summary ───────────────────────────────────────────────────────
echo ""
echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
